TAL' AS code, 0 AS amount, 'REPORTED' AS origin UNION ALL SELECT 'THIAMIN' AS code, 0 AS amount, 'REPORTED' AS origin UNION ALL SELECT 'VITAMIN_A_RAE' AS code, 0 AS amount, 'REPORTED' AS origin UNION ALL SELECT 'VITAMIN_B12' AS code, 0 AS amount, 'REPORTED' AS origin UNION ALL SELECT 'VITAMIN_B6' AS code, 0 AS amount, 'REPORTED' AS origin UNION ALL SELECT 'VITAMIN_C' AS code, 0 AS amount, 'REPORTED' AS origin UNION ALL SELECT 'VITAMIN_D' AS code, 0 AS amount, 'REPORTED' AS origin UNION ALL SELECT 'VITAMIN_E' AS code, 0 AS amount, 'REPORTED' AS origin UNION ALL SELECT 'VITAMIN_K' AS code, 0 AS amount, 'REPORTED' AS origin UNION ALL SELECT 'WATER' AS code, 99.7 AS amount, 'REPORTED' AS origin UNION ALL SELECT 'ZINC' AS code, 0.02 AS amount, 'REPORTED' AS origin) v JOIN nutrient_definitions n ON n.code = v.code JOIN foods f ON f.source_food_ref = '14355' JOIN food_data_sources s ON s.id = f.source_id AND s.code = 'USDA_SR28';
INSERT INTO food_portions (food_id, label, unit, unit_quantity, basis_amount, is_default, source_note) SELECT f.id, '1 fl oz', 'PIECE', 1, 29.6, TRUE, 'USDA SR28 household measure' FROM foods f JOIN food_data_sources s ON s.id = f.source_id WHERE s.code = 'USDA_SR28' AND f.source_food_ref = '14355';
